def count_duplic(lst):
    if not lst:
        return ([], [])

    unique_elements = []
    counts = []

    current = lst[0]
    count = 1

    for i in range(1, len(lst)):
        if lst[i] == current:
            count += 1
        else:
            unique_elements.append(current)
            counts.append(count)
            current = lst[i]
            count = 1

    unique_elements.append(current)
    counts.append(count)

    return (unique_elements, counts)
```

